  "about.founder.p1": "侬好，我是康塞普西翁，Luminous StockHaven 个创始人。",
  "about.founder.p2": "我弗是啥大科技公司出来个，也弗坐勒公司办公室里向。我是个小零售商，跟侬一样。我管牢五家电子商务商店，专门做书搭仔书迷个手工配饰。\n搭界交关独立零售商一样，我勒拉管多地方个库存、拿出版社个 ISBN 搭仔我自家个手工 SKU 一道跟踪、用笨重个电子表格处理供应商订单个辰光，到了崩溃个边缘。我寻帮助个应用个辰光，试了六种弗同个选择。每一种要么完全弗完整，要么糊涂得弗得了，要么就是敲竹杠——为基本工具每月收几百美元。",
  "about.founder.p3": "对一个压榨独立创作者个行业失望之后，我决定造我自家个解决方案。我造 Luminous StockHaven 是出于必要，为了拿我自家个生意做得清爽、高效、心定。",
  "about.founder.p4": "我决定拿 tis 平台以诚实、实惠个价格向公众开放，因为每个小商家侪值得有真正好用、又弗危及生计个工具。阿拉是独立拥有个，阿拉坚决守护阿拉个社区，阿拉是由一个零售商为零售商造个。",
