  "training.lessons.lost-email-recovery.step1": "勿要慌，也勿要新建账号——新邮箱会开启一个全新个、空个店铺。侬个店铺仍勒侬离开时个原处。",
  "training.lessons.lost-email-recovery.step2": "勒登录页面，点“呒没办法访问侬个邮箱？”。输入侬个账号邮箱并使用一把备用钥匙：备用验证码，或发送到侬备用邮箱个6位验证码。",
  "training.lessons.lost-email-recovery.step3": "搿只会打开一步：更改侬个账号邮箱。输入侬好访问个邮箱，并输入发送到搿个邮箱个验证码。侬个店铺、库存、团队搭历史侪会转移到新邮箱——勿会丢失任意东西。",
  "training.lessons.lost-email-recovery.step4": "完成后，侬会恢复正常登录。请立即前往“设置 → 安全搭备用钥匙”，为新邮箱设置新个备用钥匙。",
  "training.lessons.lost-email-recovery.title": "如果侬呒没办法访问侬个邮箱",
  "training.lessons.owner-staff-email-fix.step1": "如果团队成员呒没办法访问其被添加时所用个邮箱，伊拉可能根本勿需要侬：伊拉自己个备用钥匙（伊个“设置 → 安全”里向个备用验证码或备用邮箱）让伊拉好从登录页面自行更改账号邮箱。",
  "training.lessons.owner-staff-email-fix.step2": "如果伊拉从未设置备用钥匙，侬好为伊拉修复：打开“员工”，打开伊个记录，勒迭搭更改邮箱。应用会把伊整个世界随之转移——伊拉个账号、伊拉勒侬其他店铺个记录，搭伊拉个试用历史。",
  "training.lessons.owner-staff-email-fix.step3": "搿种转移特意做成全有或全无：伊拉永远勿会同时勒两个邮箱下拥有访问权限，也勿会创建重复账号。伊拉现有个登录保持有效；通知会发送到旧地址。",
  "training.lessons.owner-staff-email-fix.step4": "之后，请让伊拉登录并设置备用钥匙（伊拉个培训中有专门课程），搿能下次伊拉好勒两分钟内自救。",
  "training.lessons.owner-staff-email-fix.step5": "如果对方还记得自己的电子邮件但忘记了密码，您可以亲自发送重置：在“员工”中对方的卡片上，选择“发送密码重置”。链接和验证码会发送到对方的电子邮件，10 分钟内有效——您永远不会看到它们。所有套餐都可以使用，且只有所有者可以发送。",
  "training.lessons.owner-staff-email-fix.title": "当团队成员被锁勒外头时：修复伊个邮箱",
  "training.lessons.spare-keys-setup.step1": "侬个账号存于侬个邮箱下头。如果侬以后呒没办法访问搿个邮箱——被锁定、更换服务商、任意情况——备用钥匙就是侬回来个方法。现在就设置伊拉，趁一切正常时。",
  "training.lessons.spare-keys-setup.step2": "打开“设置”，寻到“安全搭备用钥匙”。选择“生成备用验证码”：侬会看到十个一次性验证码。伊拉只显示一次，因此请打印或抄写下来并妥善保管。",
  "training.lessons.spare-keys-setup.step3": "勒同一部分，添加备用邮箱——侬掌握个第二个地址——并输入阿拉发送到迭搭个6位验证码以验证伊。任意一把备用钥匙侪能救侬；两者侪有最好。",
  "training.lessons.spare-keys-setup.step4": "绝勿要搭啥人共享侬个验证码，也绝勿要勒搿只应用个恢复页面以外个任意地方输入伊拉。如果验证码快用完了，请生成新个一套——旧个会停止工作。",
  "training.lessons.spare-keys-setup.step5": "您也可以在同一个“安全”部分更改密码——如果密码曾被分享或写下来过，这很有用。输入您当前的密码，然后输入两次新密码。所有其他设备都会退出登录；您正在使用的设备会保持登录状态。",
  "training.lessons.spare-keys-setup.title": "侬个备用钥匙：勒需要之前设置好",
  "purchasing.sendOrder": "发送订单",
  "purchasing.sendAgain": "再次发送",
  "purchasing.sentFlash": "订单 {number} 已通过邮件发送到 {email}。",
  "purchasing.sentTo": "已发送到 {email} · {date}",
  "purchasing.sendFailed": "订单呒没办法发送。",
  "training.lessons.mgr-send-supplier-order.step1": "订单下单后，勒“采购”页面点“发送订单”，伊会直接从应用内发给供应商。草稿呒没办法发送——请先下单。",
  "training.lessons.mgr-send-supplier-order.step2": "供应商需要勒伊个“供应商”记录上有邮箱地址。如果缺失，应用会停止并告诉侬先添加——任意东西侪勿会勒未真正发送时悄悄发送或标记为已发送。",
  "training.lessons.mgr-send-supplier-order.step3": "供应商会收到一封附有订单 PDF 个邮件，只以本店个名义发送——邮件搭文档带有生意个名称，绝勿带应用个名称。",
  "training.lessons.mgr-send-supplier-order.step4": "订单随后会显示发送给了谁搭何时发送，如果有变化侬好再次发送。如果供应商要求侬通过伊拉自己个网站订货，请继续迭能做——从搿搭发送是一种选择，绝勿是锁定。",
  "training.lessons.mgr-send-supplier-order.title": "向供应商发送订单",
  "training.lessons.owner-send-supplier-order.step1": "任意已下单个采购订单侪好从“采购”页面通过邮件发送给伊个供应商——无需打印，无需单独个邮件应用。发送功能位于“供应商搭采购”，属于 Business 套餐。",
  "training.lessons.owner-send-supplier-order.step2": "发送需要供应商记录上个邮箱地址。呒没邮箱，应用会直言拒绝并告诉侬先添加，并且只有勒邮件真正发出后，订单才会被记录为已发送。",
  "training.lessons.owner-send-supplier-order.step3": "供应商收到个内容只带有侬生意个名称——侬个名称勒邮件上搭所附个订单 PDF 上；应用个名称勿会出现在伊拉看到个任意地方。",
  "training.lessons.owner-send-supplier-order.step4": "每次发送侪记录勒订单本身——已发送、何时、发送到哪个地址——重新发送会更新伊。要求通过伊个自己网站订货个供应商保留搿个流程；从应用发送永远勿会取代或阻挡伊。",
  "training.lessons.owner-send-supplier-order.title": "通过邮件向供应商发送订单（Business 套餐）",
  "training.lessons.owner-trial-reminders.step1": "勒侬自己个7天试用期间，应用会自行提醒侬——向侬订阅所用个地址发送两封邮件：一封勒试用第4天，一封勒试用结束前24小时。呒没其他邮件，付费套餐永远勿会收到提醒。",
  "training.lessons.owner-trial-reminders.step2": "勒应用里向，随着结束临近，三条简短通知会逐一出现：“侬个试用还剩5天。”，然后“侬个试用还剩3天。”，然后“侬个试用会勒24小时后结束。”试用一结束或转为付费套餐，伊拉就会消失。",
  "training.lessons.owner-trial-reminders.step3": "取消位于“设置”个“账单”下。如果侬勒试用期间取消，侬仍保留完整个7天——并且因为侬已取消，最后一封邮件会改变说法：伊会直言告诉侬勿会有任意扣款，侬个套餐就搿个结束。",
  "training.lessons.owner-trial-reminders.step4": "每封提醒邮件只发送一次——应用会记录已发送个内容，因此重启搭重复检查永远勿会给侬发两次。侬处于试用期个客户会为伊拉自己个订阅收到完全相同个提醒。",
  "training.lessons.owner-trial-reminders.title": "侬个试用提醒：啥会到达，何时到达",
  "settings.delete.cancelFirstHeadline": "删除前请先取消侬个订阅。",
  "settings.delete.cancelFirstBody": "侬要删除账号——搿并勿意味着侬取消了订阅。请先取消订阅，然后勒侬准备好时随时删除账号。",
