  "pos.shopify.domainPlaceholder": "your-store.myshopify.com",
  "pos.shopify.help": "Shopify POS 销售就是 Shopify 订单。连接搿个店铺，每个订单侪会自动从搿搭个库存中扣除伊个商品。",
  "pos.shopify.tokenNote": "令牌来自侬 Shopify 后台个自定义应用。伊只存储勒服务器上，永远勿会再次显示。",
  "pos.shopify.tokenPlaceholder": "来自侬 Shopify 自定义应用个访问令牌",
