  "pos.square.failedToast": "Square 未能完成连接。侬好重试。",
  "pos.square.help": "连接 Square，收银台个每笔销售侪会自动从搿搭个库存中扣除伊个商品——无需勒一天结束时输入任意内容。",
  "pos.square.notConfigured": "Square 连接还呒没开启。下头个 CSV 导入今天即可使用。",
  "pos.subtitle": "连接侬个收银机，收银台个一笔销售就会自动从搿搭个库存中扣除搿个商品。任意东西永远勿会重复计数。",
  "pos.title": "收银机连接",
  "pos.webhookPending": "阿拉搿边个销售 Webhook 还呒没开启——连接已保存，Webhook 一开启，销售就会开始到达。",
  "training.lessons.owner-pos-connect-shopify.step1": "收银机连接是 Business 套餐个一部分。Shopify POS 销售就是 Shopify 订单，因此连接按店铺进行：勒 Shopify 里向，为侬个店铺创建一个自定义应用并复制伊个访问令牌。勒“收银机连接”页面，粘贴侬个店铺域名（如 your-store.myshopify.com）搭令牌。",
  "training.lessons.owner-pos-connect-shopify.step2": "令牌只存储勒服务器上——伊永远勿会再次显示，连侬也看勿到。如果侬粘贴新个，伊只会替换旧个。",
  "training.lessons.owner-pos-connect-shopify.step3": "如果侬有多个位置，请选择搿个店铺个销售从哪个位置扣除。然后每个订单——无论勒 Shopify 收银台还是勒线——侪会自动从搿搭个库存中扣除伊个商品。",
  "training.lessons.owner-pos-connect-shopify.step4": "一家店铺勒搿搭连接到一个工作区。如果某个域名已勒其他地方连接，应用会直言相告，而勿是共享伊。",
  "training.lessons.owner-pos-connect-shopify.title": "连接 Shopify POS",
  "training.lessons.owner-pos-connect-square.step1": "收银机连接是 Business 套餐个一部分。打开“收银机连接”（勒“销售”菜单里向），点 Square 卡片上个“连接”。侬会进入 Square 自己个页面批准连接——应用永远勿会看到侬个 Square 密码。",
  "training.lessons.owner-pos-connect-square.step2": "回到应用后，卡片显示“已连接”。如果侬个店铺有多个位置，请选择搿个收银机个销售从哪个位置扣除；否则销售从侬个第一个位置扣除。",
  "training.lessons.owner-pos-connect-square.step3": "从那时起，每笔 Square 销售侪会自动从搿搭个库存中扣除商品。勒收银台卖出一件商品，然后查看同一页面上个“最近销售”列表：销售会勒片刻内到达，标记为已计入。",
  "training.lessons.owner-pos-connect-square.step4": "一笔销售永远勿会重复计数——如果 Square 再次发送同一笔销售，应用会识别伊且勿做任意更改。断开连接也勒同一张卡片上，伊会立即停止匹配。",
  "training.lessons.owner-pos-connect-square.title": "连接 Square：为侬移动库存个销售",
  "training.lessons.owner-pos-csv.step1": "任意能导出销售文件个收银机仍然好为侬个库存提供数据。把当天个销售导出为包含以下列个 CSV：sale_id、sold_at、sku_or_barcode、quantity——item_name 搭 location 有帮助，但可选。",
  "training.lessons.owner-pos-csv.step2": "勒“收银机连接”页面上传文件。每个 sale_id 只记录一次：明天再次上传同一文件勿会有任意变化，只会报告重复项。",
  "training.lessons.owner-pos-csv.step3": "应用呒没办法使用个行永远勿会被悄悄跳过——呒没 sale_id 个行，或数量勿是数字个行，会连同行号搭原因一起列回给侬。",
  "training.lessons.owner-pos-csv.step4": "商品按 SKU 或条形码匹配，搭实时收银机完全相同。任意未匹配个商品侪会勒匹配页面等待，搭任意其他销售一样。",
  "training.lessons.owner-pos-csv.title": "呒没收银机 API？用日终 CSV",
  "training.lessons.owner-pos-mapping.step1": "收银机商品按 SKU 或条形码搭侬个产品匹配。当一笔销售进来、带有应用从未见过个商品时，搿个商品会被暂挂——库存勿动，销售勒“收银机连接”页面个“等待匹配个商品”下等待。",
  "training.lessons.owner-pos-mapping.step2": "选择搿个商品真正对应个产品并保存。搿个匹配会被永久记住：搿个商品个每笔未来销售侪会自动计入。",
  "training.lessons.owner-pos-mapping.step3": "保存后，点“应用于暂挂销售”以计入等待里向个销售——伊拉会立即写入库存变动，带有销售自己个参考编号。",
  "training.lessons.owner-pos-mapping.step4": "如果一笔暂挂销售要求个数量超过货架上个数量，伊会保持标记为库存勿足，而勿是让数量变为负数。补货后，再从同一页面重新应用。",
  "training.lessons.owner-pos-mapping.title": "当收银机商品勿匹配时：匹配页面",
  "training.lessons.owner-pos-sales-list.step1": "“收银机连接”页面上个“最近销售”列表显示侬个收银机发送个每笔销售：哪个收银机、销售编号、何时、收银机报告个总计，搭每件商品个处理结果。",
  "training.lessons.owner-pos-sales-list.step2": "“已计入”表示库存已移动。“部分计入”表示有些商品已计入，有些勒等待或数量勿足——打开销售以通俗语言查看是哪些。",
  "training.lessons.owner-pos-sales-list.step3": "“已暂挂”表示搿个销售中还呒没任意商品计入：有商品需要匹配（见匹配课程）、货架数量勿足，或销售勒店铺勿勒 Business 套餐时到达。搿三种情况侪可从同一页面修复——因套餐暂挂个销售勒店铺回到 Business 后可从搿搭计入——且任意东西侪勿会悄无声息地丢失。",
  "training.lessons.owner-pos-sales-list.step4": "每笔已计入个销售侪会勒侬个库存历史中写入一条正常个“已售出”记录，带有指明收银机搭销售个参考编号——因此侬个“变动记录”页面搭收银机始终讲述同一个故事。",
  "training.lessons.owner-pos-sales-list.title": "阅读侬个收银机销售",
  "training.lessons.staff-pos-till-sales.step1": "如果侬个店铺勒 Business 套餐中并已连接收银机（Square 或 Shopify POS），收银台个每笔销售侪会自动从搿搭个库存中扣除搿个商品——无需扫码出库，无需事后输入。",
  "training.lessons.staff-pos-till-sales.step2": "侬好勒“收银机连接”页面上观看搿一过程：每笔销售显示售出了啥、多少，搭是否计入。已计入个销售会以通俗语言显示为已计入。",
  "training.lessons.staff-pos-till-sales.step3": "有时一笔销售会被暂挂：收银机售出了应用还呒没办法匹配到产品个商品。库存未被扣除——销售会等待，直到店主或经理把搿个商品匹配一次（匹配页面）。之后，伊会被计入，同一商品个下一笔销售会自动匹配。",
  "training.lessons.staff-pos-till-sales.step4": "如果一笔暂挂销售搭侬刚卖出个东西有关，请告诉侬个经理或店主——一次快速匹配就能永久修复伊。绝勿要手动调整库存来弥补暂挂销售；一旦匹配，那会重复计数。",
  "training.lessons.staff-pos-till-sales.title": "当收银机售出时，侬个库存会自动移动",
