  "training.lessons.owner-shipping-labels.step1": "打印中心勒两种套餐里向都有\"邮寄标签\"样式：选择一个客户订单，就可以打印一张 4×6 标签，上头有买家姓名搭地址，搭作为寄件人个侬个店铺。",
  "training.lessons.owner-shipping-labels.step2": "箇张标签搭所有客户单据一样是白标个：上头只有侬个店铺名称——永远勿会出现本应用个名称——所以从侬店里寄出个包裹看上去就是来自侬个店。",
  "training.lessons.owner-shipping-labels.step3": "客户个地址会得跟牢伊个订单保留到最后一次订单之后 90 天；假使订单存有地址，标签会得从伊个地址开始；打印辰光为一次性标签输入个地址勿会得拨保存转去。姓名还是会得从订单填进去，搿能让标签同单据对得上。",
  "training.lessons.owner-shipping-labels.step4": "箇张标签通过搭所有标签相同个四种连接打印——蓝牙、Wi-Fi、以太网搭 USB——4×6 热敏打印机是佢个标准尺寸。",
  "training.lessons.owner-shipping-labels.step5": "改为向承运商购买了邮资？在同一区域，您可以上传承运商的标签文件 — PDF、PNG 或 JPG — 它会永久保存在订单上：您的记录，以防万一，随时都在手边。它以真实的 4×6 尺寸打印。本应用从不出售邮资，所以承运商的价格是唯一的价格 — 并且永远是正确的价格。",
  "training.lessons.owner-shipping-labels.title": "客户订单邮寄标签",
  "training.lessons.print-shipping-label.step1": "订单准备好寄出个辰光，打开打印中心，选择\"邮寄标签\"样式，再选择客户订单。买家姓名会从订单自动填入。",
  "training.lessons.print-shipping-label.step2": "检查包裹要寄到个地址。当订单带有客户地址个辰光 — 会得保留到最后一次订单之后 90 天 — 伊会得自动填进去；侬在打印辰光输入个地址勿会得拨保存转去，所以打印之前请仔细核对邮编同最后一行。",
  "training.lessons.print-shipping-label.step3": "侬个店铺名称会作为寄件人打印勒顶部。假使还想拿侬个地址也印勒标签上头，就输入寄件人地址栏；勿想出现就留空。",
  "training.lessons.print-shipping-label.step4": "用 4×6 标签打印——热敏标签打印机是常见选择——或者通过浏览器打印按钮用任何打印机打印。拿标签平贴勒包裹上头，勿要折到边缘。",
  "training.lessons.print-shipping-label.step5": "如果邮资是向承运商购买的，请改为把他们的标签文件保存在订单上：在“您的承运商标签”区域上传承运商给您的 PDF、PNG 或 JPG。它会作为您的记录留在订单上，并以真实的 4×6 尺寸打印 — 而当您更愿意使用时，应用自己的地址标签也随时都在。",
  "training.lessons.print-shipping-label.title": "打印邮寄标签",
  "pos.provider.clover": "Clover",
