  "settings.install.androidSteps": "在浏览器里向，点按菜单（三个点），然后点按“安装应用”或者“添加到主屏幕”，并确认。应用会像任何其他应用一样在侬个主屏幕上。",
  "settings.install.desktopSteps": "在浏览器个地址栏里向，假使显示安装图标，请单击伊。假使呒没图标，请打开浏览器菜单并选择“安装 Luminous StockHaven”或者“添加到桌面”。",
  "staffWelcome.title": "欢迎来到 Luminous StockHaven",
  "staffWelcome.defaultGreeting": "侬好，{name}",
  "staffWelcome.defaultStoreLine": "侬现在是 {store} 个一员 — 搿家店也是侬个店。",
