  "staffWelcome.editor.title": "给新员工个欢迎消息",
  "staffWelcome.editor.description": "新员工在首次登录个辰光、在一切之前只读一遍个闲话。用侬自家个闲话来写，让伊感觉像侬个店。",
  "staffWelcome.editor.permanentNote": "第一行是应用本身 — 伊始终显示，呒没办法更改或者删脱。",
  "staffWelcome.editor.tokens": "在应该出现搿个人名字个地方写 {name}，在应该出现侬个店名个地方写 {store} — 应用会为每个人填好。",
  "staffWelcome.editor.emptyNote": "拿框留空就好用应用个标准欢迎语（在框里淡淡显示）。新员工永远勿会看到空白页面。",
  "staffWelcome.editor.save": "保存欢迎消息",
  "staffWelcome.editor.saved": "欢迎消息已保存。",
  "training.lessons.staff-shift-windows.title": "侬个登录跟牢侬个班次",
  "training.lessons.staff-shift-windows.step1": "侬好从预定班次开始前约 10 分钟起登录。在何之前，应用保持关脱 — 登录页面会告诉侬下一个班次啥辰光开始。",
  "training.lessons.staff-shift-windows.step2": "一旦侬打卡下班，侬有 10 分钟查看侬个页面，因为侬会被退出，直到侬个下一个预定日期。",
  "training.lessons.staff-shift-windows.step3": "假使侬在搿 10 分钟里向重新打卡上班，退出会被取消，侬会保持登录状态。",
  "training.lessons.staff-shift-windows.step4": "排班表上呒没班次意味着何天呒没办法登录。假使侬认为自家应该在排班表上，请问侬个经理或者所有者 — 发布打开侬大门个排班表个是伊拉。",
  "training.lessons.manager-shift-windows.title": "发布排班表会打开搭关脱访问权限",
  "training.lessons.manager-shift-windows.step1": "侬为团队发布个排班表勿仅仅是班次列表：伊打开搭关脱每个人个应用访问权限。团队成员好从侬为伊发布个班次前约 10 分钟起登录 — 勿能更早。",
  "training.lessons.manager-shift-windows.step2": "当伊打卡下班个辰光，伊有大约 10 分钟查看伊个辰光，然后应用会拿伊退出，直到伊个下一个预定班次。何天呒没发布班次意味着伊何天呒没办法登录。",
  "training.lessons.manager-shift-windows.step3": "请谨慎发布班次：缺失或者错误个班次会拿一个人锁在应用之外，而勿仅仅是排班表之外。假使有人讲伊进勿来，请先检查伊个排班表。",
  "training.lessons.manager-shift-windows.step4": "侬自家个访问权限也以同样个方式运作，只是高一个级别：所有者为侬发布个排班表会在侬个班次前约 10 分钟打开侬个窗口，并在侬打卡下班后约 10 分钟关脱侬个会话。",
  "training.lessons.owner-shift-windows.title": "班次窗口：排班表打开搭关脱访问权限",
  "training.lessons.owner-shift-windows.step1": "访问权限跟牢侬发布个排班表。员工或者经理好从伊预定班次前约 10 分钟起登录 — 勿能更早。在班次之外，应用对伊拉保持关脱，搿样店个信息就留在值班人员手里。",
  "training.lessons.owner-shift-windows.step2": "当伊拉打卡下班个辰光，伊拉有大约 10 分钟查看伊拉个辰光，然后应用会自家拿伊拉退出，直到伊拉个下一个预定班次。在搿 10 分钟里向重新打卡上班会取消退出。",
  "training.lessons.owner-shift-windows.step3": "何天呒没发布班次意味着何天呒没窗口：假使某个人勿在排班表上，伊就呒没办法登录。在劳动力里发布排班表，伊个大门就会随之打开。",
  "training.lessons.owner-shift-windows.step4": "侬是唯一一个例外：呒没人给所有者排班，所以侬个登录永远呒没窗口。经理受侬为伊发布个排班表个限制，就像员工受为伊拉发布个排班表个限制一样。",
  "settings.install.ownerNote": "假使侬个应用商店哪天让侬呒没办法用该应用，搿个链接好让侬直接从本网站获取应用 — 勿需要商店。",
