  "apiErrors.invalidValue.recordingNotPrepared": "该只录音准备勿好 — 麻烦侬重新录一遍。",
  "training.lessons.messages-private.step5": "侬也可以发语音留言：点消息框旁边个麦克风，讲闲话，然后点停止。先听一遍 — 然后发送，要勿删除脱重新录。有人发拨侬个辰光，点播放就可以听到对方真正个声音。",
  "training.lessons.owner-messages-oversight.step5": "已读标记：团队成员看仔侬发个消息，侬会看到伊标记为已读。员工搭经理用同样个方式互相看到对方个已读标记，两面侪是。",
  "training.lessons.owner-messages-oversight.step6": "侬自家个阅读是看勿见个。侬看员工发拨侬个消息，对方永远看勿到已读标记 — 而且侬勿需要告诉团队，伊拉个对话保存在应用里向，侬作为店主可以看。搿种监督是侬照看店铺个一部分。",
  "training.lessons.owner-messages-oversight.step7": "对于员工之间个负面消息，侬哪能处理由侬决定。可以由伊去，私下搭人讲讲，或者采取行动 — 选择权勒侬手里，侬永远勿需要讲出侬是勒啥地方看到个。",
