  "settings.policies.title": "侬店里个政策搭条款",
  "settings.policies.ownerDescription": "侬个店,侬个规矩。勒该搭写下侬店里个政策搭条款 — 好直接打字,也好上传文件。每个新团队成员开始个辰光会得看见一趟,侬整个团队啥辰光都好勒该搭看。只有侬好改伊拉。",
  "settings.policies.memberDescription": "侬店自家个政策搭条款,是店主写个。只有店主好改伊拉。",
