  "settings.platformPolicies.description": "应用本身个条款搭政策。伊拉搭应用勒一道保留,团队里每个人都好勒该搭看。",
  "staffWelcome.policiesIntro": "勒侬开始以前:侬店里个政策搭条款,是店主写个。",
  "plansLib.includes.storePolicies": "勒设置里侬自家店个政策搭条款,拨侬整个团队看",
  "apiErrors.businessPoliciesOwnerOnly": "只有店主好改该家店个政策搭条款。",
  "apiErrors.policyFileInvalid": "请发送小于 25 MB 个 PDF、文字、Word 或者 OpenDocument 文件。",
  "apiErrors.policyTextTooLong": "该份文档太长,勒该搭打勿进。侬好改成拿伊当文件上传。",
  "training.lessons.owner-store-policies.title": "侬店里个政策搭条款",
  "training.lessons.owner-store-policies.step1": "打开设置,寻着“店政策搭条款”卡片。里向有两份文档:侬个店政策 — 侬店里个家规 — 搭侬个条款搭条件。",
  "training.lessons.owner-store-policies.step2": "每份文档都好直接勒该搭打字,也好当文件上传(PDF、文字、Word 或者 OpenDocument,顶大 25 MB)。两样里向只好拣一样:保存文字会得调换文件,上传文件会得调换文字。移除一份文档会得拿伊清空。",
  "training.lessons.owner-store-policies.step3": "侬个团队会得勒伊拉头一趟开始个辰光个欢迎页面浪看见该两份文档一趟,以后啥辰光都好勒伊拉个设置里看。对侬个团队来讲,伊拉是只读个 — 只有侬好写或者改伊拉。",
  "training.lessons.owner-store-policies.step4": "每家商户侪保存自家个文档:侬勒该搭写个物事只属于该家店,永远勿会出现勒另一家商户里向。Luminous StockHaven 自家个条款搭政策勒设置里侬文档个旁边,每个人也侪好看伊拉。",
  "training.lessons.welcome-basics.step5": "侬店里个政策搭条款会得勒侬个欢迎页面浪显示一趟,搭仔保留勒设置里,侬啥辰光都好勒该搭看。",
