  "staff.memberDialog.lowStockAccessHint": "勾上第一个，搿个人就可以看到库存勿足提醒 — “需要注意”框、库存勿足页面搭低级别标记。勾上第二个，伊就可以更改产品个补货点；呒没勾，补货点输入框还是会显示，但是更改勿会保存。",
  "apiErrors.reorderChangeReserved": "只有店主，或者经店主允许更改补货点个团队成员，才好更改补货点。",
