  "settings.policyQuiz.expectedHint": "用侬自家个闲话写下侬期望个答案。差勿多一个字一个字侪对上个答案会得当场算正确；其他个会得送到侬搿搭来看。",
  "settings.policyQuiz.hint": "就搿份文件为侬个团队写点问题。假使侬在某个人个员工记录里向勾选搿项培训，伊拉会在培训里向回答搿些问题。问题个数量呒没上限。",
