  "settings.policyQuiz.title": "拨侬团队个问题",
  "staff.memberDialog.trainingAccessHint": "看店铺政策同条款是大家侪好看个。搿些勾选项分配个是所有者在设置里向每份文件旁边建立个测验培训。",
  "staffLib.area.trainingAccess": "政策测验培训",
  "staffLib.perm.trainingPoliciesQuiz": "店铺政策测验培训",
  "staffLib.perm.trainingTermsQuiz": "条款同条件测验培训",
  "training.comment.placeholder": "关于搿节课个任何想法…",
  "training.comment.send": "发送留言",
  "training.comment.sent": "侬个留言已经提交拨所有者哉。",
  "training.comment.title": "拨所有者留言",
  "training.lessons.download-app.step1": "Luminous StockHaven 好像真正个应用一样装在侬个手机或者电脑高头 — 勿需要应用商店。",
  "training.lessons.download-app.step2": "打开设置，寻着下载应用卡片。每个角色、两种套餐侪有搿张卡片。",
  "training.lessons.download-app.step3": "点安装按钮，按照设备个提示来操作。应用会得带着店铺个名字同图标出现在主屏幕高头。",
  "training.lessons.download-app.step4": "从伊个辰光开始就从主屏幕打开伊 — 登录方式一样，显示个也是同一家店铺。",
  "training.lessons.download-app.title": "拿应用下载到侬个设备",
  "training.lessons.mgr-tax-rate.step1": "订单好带一个销售税率。税率本身是所有者在设置里向定个；整个店铺只有一个税率。",
  "training.lessons.mgr-tax-rate.step2": "当所有者在侬个员工记录里向为侬勾选税费部分个辰光，税率也会得出现在侬个设置里向，侬好在伊面保持伊最新。",
  "training.lessons.mgr-tax-rate.step3": "税率是一个百分比 — 8.25 表示顾客在订单商品金额之外还要付 8.25% 个税。",
  "training.lessons.mgr-tax-rate.step4": "税率变个辰光，新订单用新税率。已经下个订单保留下单辰光个税率。",
  "training.lessons.mgr-tax-rate.step5": "若是店主拿税额切到自动，新订单会勒州出现勒订单上个辰光，用顾客所在州个基本税率填入税额，州变脱个辰光还会重新填。搿些是各州个基本税率；地方税可能还会增加。呒没州、或者来自美国境外个订单，用商店个固定税率——而勒订单上输入个税额永远优先。",
  "training.lessons.mgr-tax-rate.title": "店铺个税率",
  "training.lessons.owner-confidentiality.step5": "搿是全貌。侬个团队看到个是伊拉自家个工作 — 伊拉个排班、任务、工资单、消息，还有伊拉角色好打开个店铺页面。伊拉永远看勿到侬个试用、企业用个是啥个套餐、套餐几钿、付款有成功伐，或者有达到套餐上限伐。牵涉到钞票个页面 — 账单、发票、付款方式 — 永远只有所有者好看。",
  "training.lessons.owner-confidentiality.step6": "假使账户拨停用，侬个团队看到个正是搿条消息：“更改目前已经关脱。目前呒没办法添加或者更改任何内容 — 假使侬需要啥，请问商家所有者。” 里向呒没提到套餐、价格或者付款。",
  "training.lessons.owner-confidentiality.step7": "而当套餐上限导致某桩事体拨拦牢个辰光，显示个正是搿条消息：“搿个现在呒没办法添加 — 请问企业所有者。” 伊从来勿讲达到上限哉 — 伊桩事体只在侬同应用之间。",
  "training.lessons.staff-builds.step1": "组合是拿产品拼成一个好出售个物事 — 礼包、套装、礼品套装。组合在菜单个组合页面里向。",
  "training.lessons.staff-builds.step2": "打开一个组合，看看伊个组成：每个部件产品，还有组合各用几化个。",
  "training.lessons.staff-builds.step3": "组合拨制作或者售出个辰光，伊个部件个库存会得跟牢变 — 应用会得为侬保持数量准确。",
  "training.lessons.staff-builds.step4": "假使缺脱某个部件或者数量看起来勿对，请告诉侬个经理，勿要瞎猜 — 组合会得同时影响交关产品。",
  "training.lessons.staff-builds.title": "组合同礼包",
  "training.lessons.staff-cross-store.step1": "当侬个企业有勿止一家店铺或者网点个辰光，店铺之间好互相请求库存。搿些请求会得进到跨店收件箱里向。",
  "training.lessons.staff-cross-store.step2": "从菜单打开收件箱，看看另外一家店铺在请求啥，还有侬个店铺收到啥。",
  "training.lessons.staff-cross-store.step3": "只按照经理教侬个方式回复请求 — 发出库存会得改变侬自家店铺个数量。",
  "training.lessons.staff-cross-store.step4": "假使请求看起来勿对 — 物事错脱哉，或者数量超过侬有个 — 勿要瞎猜。请向经理报告。",
  "training.lessons.staff-cross-store.title": "跨店收件箱",
  "training.lessons.staff-reports.step1": "报表拿店铺个数字 — 销售、库存等等 — 汇总到一淘。报表在菜单里向。",
  "training.lessons.staff-reports.step2": "打开一份报表，看看伊所涵盖日期个数字。日期是报表个一部分：同一份报表换一个礼拜，讲个就是另外一个故事。",
  "training.lessons.staff-reports.step3": "有些报表好保存成功文件导出。只有在经理或者所有者要求个辰光，才拿报表导出保存。",
  "training.lessons.staff-reports.step4": "报表个数字来自店铺个真实工作 — 订单、盘点同调动 — 所以其他地方侪如实录入，报表才会得真实。",
  "training.lessons.staff-reports.title": "看报表",
  "training.lessons.welcome-basics.step6": "做好之后请退出登录：每个页面最底下、版权行正上头侪有一个退出登录链接。退出登录会得在所有设备高头侪退出 — 搿能让啥人侪勿好在共用屏幕高头进到侬个账户。",
