  "training.lessons.your-profile-photo.title": "侬个个人照片",
  "training.lessons.your-profile-photo.step1": "所有者批准仔之后，侬个照片会出现勒应用顶部侬名字旁边、「员工」页面浪，还有侬消息旁边。勒批准之前，只会显示侬名字个缩写。",
  "training.lessons.your-profile-photo.step2": "打开「设置」，寻到「侬个个人照片」。拣一张侬自家个照片发送出去。照片会发送拨所有者批准——勒等待个辰光勿会出现勒任何地方。",
  "training.lessons.your-profile-photo.step3": "所有者批准仔之后，侬个铃铛会响，侬个照片就开始显示。如果朆获得批准，拣一张勿同个照片再发送。",
  "training.lessons.your-profile-photo.step4": "换照片个做法一样：新照片要等批准，新照片批准之前，侬现在个照片保持勿变。如果换照片朆获得批准，侬保留另外一张。",
  "training.lessons.owner-profile-photos.title": "个人照片搭侬个名字",
  "training.lessons.owner-profile-photos.step1": "每个人个照片侪会显示勒伊名字旁边——勒应用顶部、侬个「员工」页面浪，还有伊拉消息旁边。团队成员个照片勒侬批准之前勿会出现勒任何地方——批准权只属于侬，呒没人好批准自家个照片。",
  "training.lessons.owner-profile-photos.step2": "有人发送照片个辰光，侬个铃铛会响。打开「员工」页面看一看，然后拣「批准」或者「勿批准」。如果侬勿批准，系统会通知对方拣另外一张照片。",
  "training.lessons.owner-profile-photos.step3": "如果有人换照片，新照片同样要等侬批准。勒等待个辰光，伊现在个照片保持勿变——如果侬勿批准更换，照片也会继续保留。",
  "training.lessons.owner-profile-photos.step4": "侬自家个照片勿需要批准：勒「设置」个「侬个个人照片」下面设定。同一张卡片里向还有侬个名字——侬勒伊面设定个名字会勒团队看到个所有地方替代「所有者」搿个词，包括应用里向搭「消息」里向。",
