  "training.lessons.mgr-clock-callin.title": "临时叫班搭考勤修正",
  "training.lessons.mgr-clock-callin.step1": "店主好给经理两只分开个勾。临时叫班让侬好为一名员工打开叫班窗口，考勤牌搭漏打个下班卡让侬好看到团队个考勤牌，还好勒员工页面修正考勤记录。每只勾自家独立起作用 — 经理好只有一只，呒没另外一只。",
  "training.lessons.mgr-clock-callin.step2": "叫班窗口让一个人勒呒没班次覆盖个辰光也好登录搭打卡。勒员工页面，从“叫班搭漏打下班卡”卡片打开伊。",
  "training.lessons.mgr-clock-callin.step3": "窗口会一直开勒海，直到伊打了下班卡 — 后头是平常个10分钟登出宽限 — 或者直到侬或者店主提前关脱伊。呒没任何物事会自动关脱伊。",
  "training.lessons.mgr-clock-callin.step4": "当有人忘记打下班卡，排班一结束，伊个记录就会勒员工页面搭工资单里向标记，侬搭店主侪会收到通知。记录会一直计时，直到修正为止。",
  "training.lessons.mgr-clock-callin.step5": "勒员工页面修正记录：设定上班、下班搭休息辰光。经理只好修正员工个记录 — 经理自家个记录由店主修正。",
