  "training.lessons.owner-staff-documents.title": "员工文件",
  "training.lessons.owner-staff-documents.step1": "侬团队里向每个人勒“员工”页面侪有一个文件档案。上传侬为伊拉保存个文书 — W-4 表格、伊拉个求职申请、税务表格、伊拉个身份证件副本 — 搭伊拉起个标题，或者保留文件名。",
  "training.lessons.owner-staff-documents.step2": "每次上传侪会保留。添加较新个版本永远勿会删除旧版本 — 所有版本侪会留勒列表里向，最新个勒前头，每个版本侪有自家个日期搭上传者姓名。",
  "training.lessons.owner-staff-documents.step3": "只有侬好看到员工文件，除非侬勒某位经理个成员记录里向授予伊“员工文件”勾选。箇个勾选默认关脱，任何角色侪勿自带。",
  "training.lessons.owner-staff-documents.step4": "勒勾选打开之前，会有一条警告说明伊个含义：箇个人将好看到有关侬员工成员个机密信息，包括社会安全号码搭出生日期。文件所属个人好打开自家个档案来看、下载搭打印 — 但是永远改勿了里向任何一样物事。",
  "training.lessons.mgr-staff-documents.title": "员工文件",
  "training.lessons.mgr-staff-documents.step1": "店主已将“员工文件”勾选托付给侬。勒“员工”页面，侬好打开团队里向员工成员个文件档案。",
  "training.lessons.mgr-staff-documents.step2": "每个档案侪保留每个版本：当侬添加较新个副本个辰光，旧副本仍旧列勒伊下头，最新个勒前头，每个版本侪有自家个日期搭上传者姓名。",
  "training.lessons.mgr-staff-documents.step3": "箇些档案里向可能有社会安全号码、出生日期搭其他私人信息。只打开侬需要个内容，永远勿要将文件分享到企业之外。",
  "training.lessons.mgr-staff-documents.step4": "店主好随时收回勾选，门会立即关脱。经理自家个文件只留勒店主搭 — 其他经理侪打开勿了，但是同所有人一样，侬也好打开自家个档案来看。",
  "nav.group.restaurant": "餐厅",
  "nav.recipes": "配方搭菜",
  "nav.restaurant": "餐厅",
  "nav.orderGuide": "订货指引",
  "plansLib.businessIncludes.restaurant": "餐厅角落——配方自动扣减原料，并算出菜个真实成本",
  "plansLib.businessIncludes.orderGuide": "补货点搭供应商订货指引",
  "staffLib.perm.restaurantBuild": "建搭编辑配方",
  "staffLib.perm.restaurantPars": "设补货点",
  "staffLib.perm.restaurantMoney": "看菜个成本搭利润",
  "staffLib.area.restaurantAccess": "餐厅访问权限",
  "staff.memberDialog.restaurantAccessHint": "看餐厅角落对团队里向所有人侪开放。搿眼勾选是交出建配方、设补货点搭看一只菜真实成本个权限。伊侪只勒 Business 方案上有效。",
  "training.module.restaurant": "餐厅",
  "training.lessons.owner-restaurant.title": "餐厅角落，老板篇",
  "training.lessons.owner-restaurant.step1": "餐厅角落放个是侬个配方搭菜。拿配方链接到侬卖个产品，设为激活，之后每卖出一只个数只产品，伊个原料就会自家从货架上扣脱——经过订单、收银台搭扫码侪一样。",
  "training.lessons.owner-restaurant.step2": "一只配方好用另外一只配方做原料——比如意大利面里向个酱汁——成本搭货架数量会经过两只一淘算上去。",
  "training.lessons.owner-restaurant.step3": "设做一趟好做出几化，搭每种原料个出成率——就是修整搭烧好之后实际好上桌个部分。真实成本是按好上桌个部分算个；货架浪向还是会扣脱侬买进来个全部数量。",
  "training.lessons.owner-restaurant.step4": "Q 因子包脱配方从来勿会列出来个小物事——盐、油、一眼柠檬汁。伊只拿个数只百分比加到菜个成本里；从来勿会从货架上扣脱啥。",
  "training.lessons.owner-restaurant.step5": "菜个钞票——真实成本搭食材成本百分比——是侬个，也属于侬交出“看菜成本”勾选个数只团队成员。其他人只会看到菜、伊个价格搭伊个原料，啥地方侪呒没成本数字。",
  "training.lessons.staff-restaurant-view.title": "看菜搭配方",
  "training.lessons.staff-restaurant-view.step1": "勒 Business 方案上，餐厅角落会列出菜搭配方。打开一只要看伊个照片、里向放啥，搭做一趟好做出几化。",
  "training.lessons.staff-restaurant-view.step2": "当一只带激活配方个菜卖出，伊个原料会自家从货架上扣脱。还是草稿个配方啥也勿扣。",
  "training.lessons.staff-restaurant-view.step3": "订货指引会告诉侬要买啥：每一种有补货点个原料，伊会算补货点减去现有搭已经订个，再按供应商个包装大小向上取整。",
  "training.lessons.staff-restaurant-view.step4": "菜个成本是老板好分享个。假使一只菜呒没显示成本，个数是故意个——需要个话问老板。",
  "training.lessons.mgr-restaurant-build.title": "建配方",
  "training.lessons.mgr-restaurant-build.step1": "老板已经拿“建配方”个勾选交给侬哉。勒餐厅角落，侬好一行一行加原料来写配方——每行侪是一只已经勒库存里向个产品，搭做一趟要用个数量。",
  "training.lessons.mgr-restaurant-build.step2": "配方也好从文件导入：每行一种原料，写伊个名称或者 SKU 搭数量。应用对勿上个行会讲给侬听，从来勿会安安静静删脱。",
  "training.lessons.mgr-restaurant-build.step3": "一只配方也好用另外一只配方做原料，配方会一径保持草稿——勿会从货架上扣脱啥——直到侬拿伊设为激活，并链接到侬卖个产品。",
  "training.lessons.mgr-restaurant-build.step4": "老老实实设每种原料个出成率：伊是修整搭烧好之后留下来个比例，菜个真实成本就是按伊算个。",
  "training.lessons.mgr-restaurant-pars.title": "设补货点搭订货指引",
  "training.lessons.mgr-restaurant-pars.step1": "老板已经拿“补货点”个勾选交给侬哉。补货点就是一种原料应该有几化现有——好是整个生意，也好是伊个一个地点。",
  "training.lessons.mgr-restaurant-pars.step2": "拿包装大小设成供应商卖搿种原料个方式——一箱十二只，一袋五十只。订货指引会拿每个缺口侪向上取整到整包。",
  "training.lessons.mgr-restaurant-pars.step3": "指引会算补货点减去现有，再减去已经订个，按供应商分组，葛么一个礼拜个采购就好按每个供应商看成一张短清单。",
  "training.lessons.mgr-restaurant-pars.step4": "送出指引会勒采购里向，为个数只供应商写一张草稿采购单——搭其他地方个采购单一样，准备好给侬检查搭送出。",
  "training.lessons.mgr-restaurant-money.title": "看菜个钞票",
  "training.lessons.mgr-restaurant-money.step1": "老板已经拿“菜个钞票”个勾选交给侬哉。菜现在会勒售价旁边显示伊个真实成本——原料个成本，经过伊里向任何配方一淘算上去。",
  "training.lessons.mgr-restaurant-money.step2": "食材成本百分比是真实成本除以售价。伊是按每种原料好上桌个部分算个，也就是算出成率之后个部分。",
  "training.lessons.mgr-restaurant-money.step3": "假使配方带 Q 因子，伊已经算勒真实成本里向哉——伊包脱配方呒没列出来个小物事，比如盐搭油。",
  "training.lessons.mgr-restaurant-money.step4": "菜个钞票只留勒生意里向。老板随便啥辰光侪好拿搿只勾选收回去，数字就会马上从侬个屏幕浪消失。",
