  "nav.xstoreMessages": "跨店消息",
  "plansLib.businessIncludes.xstoreMessages": "跨店消息——侬整个团队，遍及每一家生意",
  "xstore.title": "跨店消息",
  "xstore.help": "搿个账户浪向每个人，遍及侬所有生意，侪聚勒同一个收件箱里向。侬好勒伊面发消息给伊拉任何人——文字或者语音侪好，还有已送达同已读个标记。侬个店内消息保持原样勿变。",
  "xstore.empty": "还呒没任何对话。用「新消息」开始一段对话吧。",
  "xstore.noPeople": "还呒没其他人好发消息。大家加入侬其中一家生意并且登录之后，就会勒伊面出现。",
  "xstore.deliveredLabel": "已送达",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "跨店消息是商业版套餐里向个一部分。",
  "apiErrors.invalidValue.personNotPartAccount": "搿个人勿是搿个账户里向个人。",
  "training.lessons.owner-xstore-messages.title": "跨过侬店个消息，店主篇",
  "training.lessons.owner-xstore-messages.step1": "跨店消息是第二个收件箱，同店内消息分开。店内消息是给侬现在立勒个店用个；而搿扇门好联系着侬账户浪向每个人，遍及侬拥有个每一家生意——顶多五家。",
  "training.lessons.owner-xstore-messages.step2": "从菜单打开跨店消息，就好同名单浪任何人开始谈天。名单会显示侬所有生意里向已经登录过个每一位团队成员，连同伊拉做生活个店。",
  "training.lessons.owner-xstore-messages.step3": "照片也会一道显示：每个人侪会显示伊已经通过个头像照片，呒没照片个辰光就显示伊名字个缩写。每条消息侪带了发送个日期同辰光。",
  "training.lessons.owner-xstore-messages.step4": "勒侬自家发送个消息下头，消息送到之后侬会看见「已送达」，对方打开对话之后会看见「已读」。语音消息勒伊面也用得，同店内消息里向一式一样。",
  "training.lessons.owner-xstore-messages.step5": "伊面个对话只属于对话里向两个人私底下个事体。侬对店内消息个查看权，勿会伸到其他店伊面去。",
  "training.lessons.mgr-xstore-messages.title": "跨过侬店个消息，经理篇",
  "training.lessons.mgr-xstore-messages.step1": "跨店消息好联系着搿个账户浪向每个人，遍及每一家生意——勿单单是侬现在立勒个店。伊勒菜单里向，同店内消息是分开个。",
  "training.lessons.mgr-xstore-messages.step2": "从名单浪开始谈天：已经登录过个每一位团队成员侪勒伊面，伊拉做生活个店写勒伊拉名字旁边。",
  "training.lessons.mgr-xstore-messages.step3": "发文字，或者录一段语音消息。语音消息发送之前，侬好听转来、掼脱伊或者发送出去——同店内消息一样个。",
  "training.lessons.mgr-xstore-messages.step4": "侬个消息送到个辰光显示「已送达」，对方打开对话个辰光显示「已读」。每个名字旁边个照片，是搿个人已经通过个头像照片。",
  "training.lessons.staff-xstore-messages.title": "跨过侬店个消息",
  "training.lessons.staff-xstore-messages.step1": "跨店消息是侬好联系着搿个账户浪任何人个地方，勿管伊勒老板哪一家生意里向——想问另外一家店个事体，勿需要再等了。",
  "training.lessons.staff-xstore-messages.step2": "从菜单打开伊，拣着个人，然后写消息。假使侬要寻个人勿勒名单里向，就是伊还呒没登录——伊一登录就会出现。",
  "training.lessons.staff-xstore-messages.step3": "侬勒伊面也好发送语音消息：录音、听转来，然后发送或者掼脱伊。每条消息侪会显示发送个日期同辰光。",
  "training.lessons.staff-xstore-messages.step4": "侬发送消息个辰光，送到之后显示「已送达」，对方打开对话之后显示「已读」。对话只属于侬同对方两个人私底下个事体。",
