  "training.lessons.owner-restaurant-ops.title": "餐厅运营，老板篇",
  "training.lessons.owner-restaurant-ops.step1": "供应商发票勒餐厅角落里向。输供应商开出来个账单，链接到伊个采购单，应用会三方对账——订过、收过搭开过票，并排看——还会标出任何勿够数、多出来，或者用另外一个价开票个行。",
  "training.lessons.owner-restaurant-ops.step2": "当发票一行用搭记录成本勿一样个价给产品开票个辰光，发票页会弹出价格提醒。接受提醒会拿产品成本更新成开票价；勿理伊就留牢成本勿变。",
  "training.lessons.owner-restaurant-ops.step3": "损耗记录会记下厨房掼脱个所有物事，带牢原因——坏脱、做多了、备餐出错、退回来、泼脱，或者其他——记录伊会自家拿库存从货架浪扣脱。保质期批次按顶快到期先出排，所以顶早个保质期先用，侬也好给侬勾选个批次打印日期标签。",
  "training.lessons.owner-restaurant-ops.step4": "过敏原表会按每只菜配方个原料，对牢九大主要过敏原算伊个过敏原，让客人个问题从记录里向得到回答，勿是靠记忆。温度记录、卖光看板搭员工餐整个团队侪好用——勿需要勾选——因为日常记录只勒啥人侪做得到个辰光才行得通。",
  "training.lessons.owner-restaurant-ops.step5": "菜单工程按每只菜卖出几化搭赚到几化摆位：明星、耕马、谜题搭狗。差异页会拿配方讲应该从货架走脱个，搭员工餐、损耗搭其他所有出去个比较——剩下个就是解释勿出个部分。会计导出会拿收过货个买货、损耗、员工餐搭配方扣减，整理成一本账给侬入账。",
  "training.lessons.staff-restaurant-daily.title": "厨房个日常习惯",
  "training.lessons.staff-restaurant-daily.step1": "有物事掼脱个辰光，当日勒损耗记录里向记下：是啥、几化、搭原因——坏脱、做多了、备餐出错、退回来、泼脱，或者其他。记录伊会自家拿库存从货架浪扣脱；侬勿需要另外再改库存。",
  "training.lessons.staff-restaurant-daily.step2": "侬查每个冰箱、冷冻柜搭保温温度个辰光就记下伊。记录会留牢侬个名字搭辰光，还会标出任何出脱安全范围个读数——拿侬做了啥来处理写下做处理办法。",
  "training.lessons.staff-restaurant-daily.step3": "卖光看板就是现在啥卖光哉。物事一卖光就马上贴上看板，让整个团队马上晓得，补货个辰光清脱伊——看板会留牢啥人清搭啥辰光清。",
  "training.lessons.staff-restaurant-daily.step4": "团队吃物事个辰光，记下做员工餐。每餐侪会拿伊个菜从货架浪扣脱，搭用菜配方个原料，搭卖出一次一样。员工餐是当日个真实成本，应该记录勒账浪。",
  "training.lessons.mgr-restaurant-invoices.title": "发票、批次搭跑批次",
  "training.lessons.mgr-restaurant-invoices.step1": "老板信任侬，拨侬“建配方”个勾选，伊还会开厨房个制作工作：供应商发票、保质期批次搭批量制作。输一张供应商发票，带牢伊个行——产品、数量搭开票成本——有采购单个辰光就链接上去。",
  "training.lessons.mgr-restaurant-invoices.step2": "链接采购单之后，发票会逐行三方对账：订了啥、收了啥、开票了啥。一行好转来是对得上、勿够数、多出来、用另外一个价开票，或者根本勿勒订单浪向。",
  "training.lessons.mgr-restaurant-invoices.step3": "开票价搭产品记录成本勿一样个辰光，会弹出价格提醒。接受提醒会拿产品成本设成新个开票价；勿理伊啥也勿变。同一张发票搭同一只产品，同一辰光只会有一只开牢个提醒。",
  "training.lessons.mgr-restaurant-invoices.step4": "拿货当成一只带保质期个保质期批次收货，保质期页会留牢批次顶快到期先出。跑一次批次会拿一只配方做指定趟数：伊会用脱配方个原料，搭拿做好个备餐产品放转货架浪——配方要先链接到个数只备餐产品。",
  "training.lessons.mgr-restaurant-invoices.step5": "当供应商针对发票退回款项时——破损个箱子、短缺个交货、修正个价格——拉发票页面上针对该发票记录为贷项通知单。供应商来自发票本身，通知单计入发票还欠个金额：发票显示其已应用个贷项搭应付余额。贷项永远勿好超过其发票，作废通知单会让其留在记录里，同时停止计数。 需要纸质版个辰光，可以从箇行打印箇张凭证——打印出来个单据是侬对供应商贷项个自有记录，并非供应商个单据。",
  "training.lessons.mgr-restaurant-reports.title": "菜单工程、差异搭账",
  "training.lessons.mgr-restaurant-reports.step1": "老板信任侬，拨侬“菜钞票”个勾选，伊还会开厨房个钞票报告：菜单工程、差异搭会计导出。搿眼数字会留勒生意里向，搭所有菜钞票一样。",
  "training.lessons.mgr-restaurant-reports.step2": "菜单工程按每只菜勒个数期间卖出几化搭赚到几化摆位。明星卖得好搭赚得多；耕马卖得好但是赚得少；谜题赚得多但是卖得少；狗两样侪勿行。",
  "training.lessons.mgr-restaurant-reports.step3": "差异页按产品算：配方讲应该从货架走脱个，搭员工餐、损耗搭其他所有出库存个并排。剩下个全是解释勿出个——而解释勿出个数只数字，就是要去解释个。",
  "training.lessons.mgr-restaurant-reports.step4": "会计导出是厨房一本账：收过货个买货、损耗、员工餐搭配方扣减，每行带牢伊个日期、数量搭成本，好交给帮侬记账个人哉。",
  "apiErrors.invalidReference.recipeMustBelongBusiness": "配方要属于搿个生意。",
