  "storefronts.ebayDesc": "拿侬个 eBay 店面连接一记。当商品垃 eBay 上头卖脱个辰光，伊个数量会垃该搭自家减少，销售会记录垃侬个出入库记录里向 — 就像伊拨扫码出库一样。销售只单向流动：从 eBay 流进应用。",
