  "plansLib.includes.recordPrints": "纸质记录 — 每周排班表、工资登记表、工时表、培训记录、政策搭条款、员工名册搭价格清单，好打印已填写版或者手填空白版",
  "training.lessons.staff-record-prints.title": "纸上个记录",
  "training.lessons.staff-record-prints.step1": "应用里向几乎每条记录现在勒文档样式工作室里侪有个纸质孪生版：每周排班表、工资登记表、工时表、培训记录、侬店铺个政策搭条款、员工名册搭产品搭价格清单 — 勒 Business 套餐里还有供应商目录搭已填写个温度记录。每份侪以侬保存个文档样式、侬企业个语言打印，日期按侬个方式写。",
  "training.lessons.staff-record-prints.step2": "每份纸侪勒伊记录所在个地方。勒员工页面，排班标签打印侬看得见个每个人整周安排，考勤标签从伊记录打印工时表。打印只显示侬勒箇屏幕上已经看得见个内容 — 打印永远勿会扩大任何人个可见范围。",
  "training.lessons.staff-record-prints.step3": "勒工资页面，预览一个工资期间再打印登记表：每个人、伊工时、总额、扣除搭净额侪勒一张纸上，拨工资档案用。勒培训页面，团队部分打印培训记录 — 啥人完成了啥，附测验分数搭日期。",
  "training.lessons.staff-record-prints.step4": "侬店铺个政策搭条款从设置里打印出来，搭侬写个一式一样，准备好交拨新员工或者贴勒墙上。员工页面打印一页名册，产品页面打印价格清单，勒 Business 里供应商页面打印目录，温度记录页面为食品安全档案打印已填写个记录。",
  "training.lessons.staff-record-prints.step5": "需要一张手填个表格伐？打印中心个空白表格现在为箇些纸每份侪提供空白孪生版，两个套餐侪有：打印一张，用笔填好，搭打印件放勒一道归档。",
  "ageCheck.title": "年龄检查",
  "ageCheck.intro": "扫描驾驶证或者身份证背面的条形码。侬只会得着一个回答——绿颜色个勾或者红颜色个勾——应用从扫描里啥侬勿留：呒没名字，呒没号码，呒没出生日期，啥侬呒没写下来。",
  "ageCheck.scanPrompt": "拿摄像头对准证件或者卡背面的条形码。",
  "ageCheck.categoryLabel": "勒拉卖啥物事？",
  "ageCheck.category.alcohol": "酒",
  "ageCheck.category.tobacco": "香烟",
  "ageCheck.category.other": "其他有年龄限制个货色",
  "ageCheck.lineNote": "侬对{category}个线：{age}岁及以上",
  "ageCheck.pass": "年龄够了——可以卖了。",
  "ageCheck.fail": "年龄勿够——勿要做箇笔生意。",
  "ageCheck.expired": "箇张卡已经过期了——勿通过。",
  "ageCheck.unreadable": "箇个码勿是阿拉读得懂个身份证条形码。试试证件背面的条形码。",
  "ageCheck.checkAnother": "再查一个",
  "ageCheck.back": "转去扫描产品",
  "ageCheck.keepsNothing": "箇趟扫描里啥侬呒没保存、呒没发送、呒没记录。回答就是全部，离开箇个画面就呒没了。",
  "settings.ageLines.title": "年龄线",
  "settings.ageLines.description": "顾客每种生意侬要达到个年龄，扫描页面浪个年龄检查就用箇个。箇眼线是侬自家定个——按照侬生意所在地方个法律来定。应用从酒21岁、香烟21岁、其他有年龄限制个货色18岁开始。",
  "settings.ageLines.alcohol": "酒——最低年龄",
  "settings.ageLines.tobacco": "香烟——最低年龄",
  "settings.ageLines.other": "其他有年龄限制个货色——最低年龄",
  "plansLib.includes.ageCheck": "用证件扫描查年龄——扫描身份证背面得着绿颜色或者红颜色个勾，卡里啥侬呒没留",
  "training.lessons.scanner-age-check.title": "用证件扫描查年龄",
  "training.lessons.scanner-age-check.step1": "有些货色只好卖拨超过一定年龄个顾客。勒拉扫描页面浪，打开年龄检查，拣卖个是啥——酒、香烟，还是其他有年龄限制个货色——然后扫描顾客驾驶证或者身份证背面的条形码。",
  "training.lessons.scanner-age-check.step2": "回答是两个勾里向个一个。绿颜色个勾是讲顾客年龄够了，可以卖了。红颜色个勾是讲伊还呒没达到箇个类别个线，或者卡过期了——两种情况生意侬勿好做。",
  "training.lessons.scanner-age-check.step3": "应用从扫描里啥侬勿留。呒没名字、证件号码或者出生日期勒拉啥地方保存、发送或者写下来：检查回答箇一个问题就呒没了。呒没查过个卡个名单好转去看个——箇是特意设计个。",
  "training.lessons.scanner-age-check.step4": "年龄线是老板个，伊勒拉设置里按照生意所在地方个法律来定。伊好搭地方搭地方勿一样，也好搭应用个起始线勿一样，检查永远跟牢侬所在生意个老板个线。",
  "training.lessons.scanner-age-check.step5": "假使码读勿出，画面会讲得清清爽爽。拿条形码揩揩清爽再试一趟，或者请伊出示另外一张卡。勿是身份证条形码个码永远得勿着绿颜色个勾。",
  "training.heading.general": "通用培训",
