  "training.own.title": "添加侬自家个培训",
  "training.own.help": "写一份侬自家个培训——侬个安全规则、侬个注意事项、侬做事体个方法——然后做伊个测验，并勾选应该参加个人。侬个培训只留垃迭个企业里；其他企业个任何人侪永远看弗到。",
