  "training.own.sectionHelp": "侬个店主为迭家店写了迭些培训。逐个阅读，然后回答店主个问题。",
  "training.own.read": "培训",
  "training.own.noMaterial": "店主还呒没添加培训文字。",
  "training.own.pendingNote": "侬个答案垃店主此地。当店主标记为通过个辰光，迭个培训才算完成。",
  "plansLib.includes.ownTraining": "添加侬自家个培训——为侬个团队编写自家个培训搭测验",
  "training.lessons.owner-own-training.title": "添加侬自家个培训",
  "training.lessons.owner-own-training.step1": "垃培训页面个最末脚有“添加侬自家个培训”框。打开伊，开始一个新培训，并给伊一个标题——侬个安全规则、侬个注意事项、侬做事体个方法。",
  "training.lessons.owner-own-training.step2": "垃框里用侬自家个闲话写培训内容本身，或者改为上传文件——PDF、文本、Word 或者 OpenDocument 文件。输入个文字会替换已保存个文件，文件也会替换输入个文字。",
  "training.lessons.owner-own-training.step3": "垃下面做伊个测验：想要多少题都可以，选择题搭书面回答题自由混合。对于书面题，写下侬期望个答案；对于选择题，标记正确个那个。",
  "training.lessons.owner-own-training.step4": "设定通过线，并选择书面回答个判定方式：用侬个答案钥匙几乎逐字核对，或者发给侬来标记通过或者退回。然后准确勾选哪些团队成员参加迭个培训——只有伊拉好看见。",
  "training.lessons.owner-own-training.step5": "侬保存个每个培训侪垃框里独立存在，有自家个问题、通过线搭勾选，侬可以添加任意多个。结果会出现垃每个培训下头个框里；只有当服务器核查了一次通过个作答，培训才算完成——或者垃批改模式下，当侬标记为通过个辰光。",
  "apiErrors.ownTrainingOwnerWrites": "迭些培训只有店主能写。",
  "apiErrors.ownTrainingNotHere": "那个培训弗垃此地。",
  "apiErrors.ownTrainingTooLong": "那个培训太长，没办法垃此地输入。侬可以改为上传文件。",
