  "scan.pool.body": "箇还勿是侬店里个商品——是侬预先打印个条形码。侬想担伊添加为商品伐？",
  "plansLib.includes.barcodePool": "条形码池——预先打印条形码，然后勒每个商品个条形码被扫描个辰光添加该商品",
  "training.lessons.owner-barcode-pool.title": "勒商品之前打印条形码",
  "training.lessons.owner-barcode-pool.step1": "有些商品呒没自家个条形码——手工制品、侬自家个书包、任何侬亲手做或者组合个物事。勒打印部分，“生成条形码”入口会勒商品存在之前就生成编码。",
  "training.lessons.owner-barcode-pool.step2": "讲出侬需要个数量——呒没上限——应用就会向侬企业个条形码池铸造同样数量个新码。伊拉只属于侬个企业，绝对勿会发放两次，生成伊拉也勿会产生商品或者库存。",
  "training.lessons.owner-barcode-pool.step3": "勒伊拉生成个哀一刻做出选择：马上打印成标签，或者保存为 PDF 以便日后打印。无论哪种方式，箇些码侪勒池里，打印出来个标签搭码池完全一致。",
  "training.lessons.owner-barcode-pool.step4": "勒做每件商品个辰光给伊贴上一个标签。未使用个码只不过勒池里等待——勿用着急，伊拉也勿会过期。",
  "training.lessons.owner-barcode-pool.step5": "当贴有标签个商品日后被扫描个辰光，应用会认出伊自家打印个码，并提议添加该商品，码已经填好。添加之后，箇个码就成为该商品个码，像其他任何码一样被扫描。",
  "apiErrors.poolOwnerMints": "只有店主才好为码池生成条形码。",
  "apiErrors.poolCount": "讲出侬需要多少个条形码——一个整数，一个或者更多。",
