  "training.lessons.staff-checklists.title": "做清单",
  "training.lessons.staff-checklists.step1": "清单是侬盘生意运转所靠个清单——开店、打烊、清洁,搭仔店主设定个一切。勒“清单”里向寻到渠拉:今朝个清单勒最上面,准备好勾选。",
  "training.lessons.staff-checklists.step2": "当侬真正做完一个项目个辰光再勾选渠。每个勾选侪会记下是啥人做个、啥辰光做个,箇浪下一个人——搭仔勒屋里个店主——侪可以看到啥做完了、啥还没做。",
  "training.lessons.staff-checklists.step3": "有些项目勒勾选之前要求证明:做完工作个照片、代码个扫描,或者输入个温度。先加证明,再勾选——没证明,项目勿会被勾选。",
  "training.lessons.staff-checklists.step4": "勿小心勾选了啥?取消渠个勾选——但只能取消自家个。经理或者店主可以取消任何人个,因为勾选是带名字个记录。",
  "training.lessons.staff-checklists.step5": "做清单从来勿需要许可。建立模板并选择分配畀啥人是店主个工作,或者店主畀清单模板勾选个人个工作。",
