  "training.lessons.staff-food-safety.title": "维护食品安全档案",
  "training.lessons.staff-food-safety.step1": "食品安全档案位于餐厅角落的食品安全货架上：温度日志、冷却、复热和消毒剂日志、证书、安全数据表和检查包。",
  "training.lessons.staff-food-safety.step2": "超出范围的读数在其备注说明你做了什么 — 重新冷却、重新加热、重新配制消毒剂、丢弃 — 之前不算完成。没有备注，就不保存：该条目不成立。",
  "training.lessons.staff-food-safety.step3": "像记录温度一样记录冷却、复热和消毒剂检查：你检查了什么、读数，以及未达标时的纠正措施。",
  "training.lessons.staff-food-safety.step4": "证书在到期前会发出警告。当你的证书发出警告时，告诉业主 — 任何人都可以随时在货架上阅读安全数据表。",
  "training.lessons.staff-food-safety.step5": "在检查之前 — 或任何时候 — 从食品安全货架运行模拟检查，并按检查员的日期打印检查就绪包。",
