  "training.lessons.staff-kitchen-menu.step1": "从厨房搭食谱架打开厨房显示屏，拣侬正勒烧个食谱。",
  "training.lessons.staff-kitchen-menu.step2": "点选侬要做个批次数。画面上每个用量侪会得重新计算——照画面烧，勿要凭记忆。",
