  "training.lessons.staff-equipment.title": "设备记录搭报告故障",
  "training.lessons.staff-equipment.step1": "侬生意里向个每台机器勒设备里向侪有自家个页面：啥辰光买个、保修啥辰光结束、由谁维修，以及发生过个一切。",
  "training.lessons.staff-equipment.step2": "当有物事坏脱个辰光，就勒机器本身浪报告。讲出啥坏脱了，如果可以，附上问题照片 — 报告会带着侬个名字搭辰光进入机器个历史。",
  "training.lessons.staff-equipment.step3": "只有当店主授予侬故障报告勾选个辰光，侬才可以报告故障。如果按钮呒没勒里向，请告诉店主或者经理，伊拉会为侬开门。",
  "training.lessons.staff-equipment.step4": "保养任务 — 清洁、除垢、维修 — 侪有到期日期。设备页面显示哪些到期、哪些逾期，让任何事体侪勿悄悄溜走。",
  "training.lessons.staff-equipment.step5": "维修搭伊个费用由店主或者经理记录。当针对侬个报告记录仔维修之后，故障会勒机器历史里向显示为已修好。",
