  "training.lessons.owner-tip-pooling.title": "小费池搭小费记录",
  "training.lessons.owner-tip-pooling.step1": "打开餐厅，再打开团队搭地点，再打开小费池。只有店主好看到小费池设置、份额搭记录。",
  "training.lessons.owner-tip-pooling.step2": "选择小费池哪能分：按小时、按岗位百分比或者按点数。应用会根据已有个排班搭打卡小时来分。",
  "training.lessons.owner-tip-pooling.step3": "选择期间，输入小费池金额，预览分配，然后保存。保存个份额会进入该期间个工资预览。",
  "training.lessons.owner-tip-pooling.step4": "准备好个辰光发布已保存个分配 — 团队成员到时只好看到自家个份额，发布之前啥也看勿到。",
  "training.lessons.owner-tip-pooling.step5": "随时保存小费记录：按人、按期间、所报小费 — 年记录会把 8% 个计算换算成表格可用个合计。应用只保存记录；勿提交任何物事。",
