  "apiErrors.laborOwner": "只有店主可以设定人工盯守数字。",
  "apiErrors.laborSettings": "请检查人工盯守数字之后再试一趟。",
  "training.lessons.owner-labor-warnings.title": "设定人工警告",
  "training.lessons.owner-labor-warnings.step1": "打开排班表，寻到盯守数字。那里向每个数字侪由侬为自家店设定。",
  "training.lessons.owner-labor-warnings.step2": "设定对侬来讲加班从每周多少小时开始，还有勒应用警告侬之前，有人可以接近到多少。",
  "training.lessons.owner-labor-warnings.step3": "设定一个班次当中啥辰光应该有休息、休息应该有几长，还有侬希望班次当中最早个开始搭最晚个结束。",
  "training.lessons.owner-labor-warnings.step4": "像平常一样排个一周。当小时接近侬个线个辰光，警告会出现勒排班表上——勒伊拉过线之前。",
  "training.lessons.owner-labor-warnings.step5": "随着团队打卡进出，同一个盯守也会扫过已工作个小时，包括呒没休个休息。",
  "training.lessons.owner-labor-target.title": "按人工目标排个一周",
  "training.lessons.owner-labor-target.step1": "勒餐厅角落个团队搭场所货架上打开人工目标。",
  "training.lessons.owner-labor-target.step2": "用百分比输入侬个人工目标，还有侬预计本周个销售额。",
  "training.lessons.owner-labor-target.step3": "勒排班表上排个一周。预计人工成本搭伊个%会根据应用里向已经有个班次搭时薪更新。",
  "training.lessons.owner-labor-target.step4": "当预计人工%超过侬个目标个辰光，页面会用明白个说话讲出来，还附上背后个工时搭成本。",
  "training.lessons.owner-labor-target.step5": "当侬想拿个一周印勒纸上个辰光，从页面打印——印出来个表格搭侬勒屏幕上看见个是同一份文件。",
