  "training.lessons.owner-reservations.title": "接受预订搭管理候位名单",
  "training.lessons.owner-reservations.step1": "勒餐厅角个“餐区搭客人”货架上打开“预订”。预订簿保存每一个预订；伊下面个候位名单保存今朝夜里直接到店个客人。",
  "training.lessons.owner-reservations.step2": "添加预订辰光填写日期搭辰光、团体个名称搭人数、电话号码，以及用侬自家个闲话写个桌台或者区域。记下厨房需要晓得个事体——过敏、高脚椅、纪念日。",
  "training.lessons.owner-reservations.step3": "询问客人是否想要提醒，只有勒伊拉讲“好”辰光才勾选该框。提醒通过电子邮件发送，短信设置好后也通过短信发送。把已收个定金——金额搭方式——只作为记录写下。",
  "training.lessons.owner-reservations.step4": "整夜推进预订簿：将每个团体标记为已入座、未到或者已取消。从预订簿将今朝个名单发送给团队，让每个人侪从同一页工作。",
  "training.lessons.owner-reservations.step5": "对于直接到店个客人，将团体连同告知个等待辰光加入候位名单。当伊拉个桌台准备好辰光，点击“桌台已准备好”——为该条短信提供号码，就是客人个同意。",
  "apiErrors.smsInvalid": "一条短信需要一个号码搭一条消息。",
  "apiErrors.smsFailed": "短信服务呒没接受箇条消息。",
