  "training.lessons.owner-standing-orders.title": "常订订单搭供应商价格比较",
  "training.lessons.owner-standing-orders.step1": "垃餐厅角个库存搭订购货架上打开常订订单。侬个重复订单垃搿搭，伊拉下面就是供应商价格簿。",
  "training.lessons.owner-standing-orders.step2": "拿常订订单设置一次：拨伊起个名字，选择伊个供应商搭对应个日脚，并用侬平常订个数量加入常备货行。",
  "training.lessons.owner-standing-orders.step3": "到仔日脚，按生成本星期草稿。本应用会垃采购部写一份草稿采购单，按价格簿里向该供应商个最新价钱计价 — 请审阅、修改任何需要个内容，并由侬亲自发送。本应用绝对勿会自家发送订单。",
  "training.lessons.owner-standing-orders.step4": "订购之前先读价格簿：一种食材，每个供应商个最新价钱并排比较，顶便宜个垃前面，带日期搭该价钱来自发票还是订单。",
  "training.lessons.owner-standing-orders.step5": "供应商发票一到就录入，让价格簿保持真实 — 每个新价钱侪会加入价格簿，下一份草稿将据此计价。",
