  "training.lessons.owner-production-order.title": "按生产下单搭自动填写个备餐单",
  "training.lessons.owner-production-order.step1": "勒餐厅角个库存搭订货货架浪打开按生产下单。生产计划 — 一趟批量生产或者一场餐饮活动 — 勒迭搭变成食材订单。",
  "training.lessons.owner-production-order.step2": "拣计划：批量生产拣食谱搭份数，或者拣一场侬已预订个餐饮活动。点计算订单。",
  "training.lessons.owner-production-order.step3": "应用会展开食谱，减脱已有库存，其余向上取到包装规格，并按供应商分组 — 订货指南个样式。",
  "training.lessons.owner-production-order.step4": "点产生草稿订单，每个供应商一张草稿采购单进到采购环节。请自家审核搭发送 — 应用绝对勿会自家发送订单。",
  "training.lessons.owner-production-order.step5": "勒备餐页，备餐单会自动填写：建议份数来自侬个标准库存量、预订搭活动里向个预订情况，搭已经备好个数量 — 建议只是展示，勒侬运行批量生产之前啥也勿会变。",
