  "training.lessons.owner-bar-counting.step1": "从库存搭订货货架开启酒吧盘点 — 勒侬开启之前伊保持隐藏，所以呒没酒吧个商家永远看勿到伊。开关只属于店主。",
  "training.lessons.owner-bar-counting.step2": "打开酒吧盘点，选择侬立勒个存放区域。该表列出该区域所存物品，每瓶搭每桶旁边都有记录在册个数量。",
  "training.lessons.owner-bar-counting.step3": "每一行说明是瓶还是桶，输入满个数量，然后将滑块移到开个那瓶看起来有几满 — 以十分之一为单位，对照伊个图片判断。盘点数是满个数量加开瓶个十分之几。",
  "training.lessons.owner-bar-counting.step4": "保存酒吧盘点。伊会作为普通盘点会话到达盘点 — 送去复核并勒伊面应用，货架就会设为侬盘点个数量。",
  "training.lessons.owner-bar-counting.step5": "酒吧盘点发现个差异会汇入理论搭实际差异，所以老是短缺个瓶子会勒伊面显形。当侬想把盘点印勒纸上个辰光，从此页面打印盘点表。",
