  "training.lessons.owner-locations-rollup.title": "所有门店在一页上",
  "training.lessons.owner-locations-rollup.step1": "打开门店货架并选择所有门店。货架本身只有在侬拥有两个或者更多企业个辰光才出现,因此只一个门店个店主永远看勿到伊。",
  "training.lessons.owner-locations-rollup.step2": "阅读每个门店个行:食材成本 %、库存价值、本周浪费搭仔库存勿足。突出个门店就是要先处理个薄弱环节。",
  "training.lessons.owner-locations-rollup.step3": "当侬想把比较结果印在纸上个辰光,打印汇总 — 伊会按屏幕上个样子打印。",
  "training.lessons.owner-locations-rollup.step4": "要复制配方,请选择伊,勾选伊应到达个门店,然后复制。配料先按 SKU 匹配,再按名称匹配;呒没匹配个会在结果当中被点名,绝对勿会被悄悄丢弃。",
  "training.lessons.owner-locations-rollup.step5": "要复制价格,请使用相同个门店勾选来复制价格搭成本。配方若伊个菜品在某个门店呒没匹配,就会以草稿形式到达搭里,等侬来关联。",
