  "training.lessons.owner-recipe-cost-link.step4": "用到该配料个每个菜谱侪会马上根据新价格重新计算成本。",
  "training.lessons.owner-recipe-cost-link.step5": "打开一个菜谱，看伊个成本更新备注，里向写明伊所依据个发票价格——成本从来勿会勿声勿响改变。",
