  "training.lessons.owner-lot-traceability.step1": "送货到达个辰光，打开库存搭订购货架上个“批次搭召回”并记录：产品、供应商、数量 — 搭每个物品箱子上盖印个批次代码。",
  "training.lessons.owner-lot-traceability.step2": "勒同一个后门屏幕上，记录冷藏品个送货温度，搭侬拒收个任何物事及原因。书面拒收正是供应商贷记所需个证据。",
  "training.lessons.owner-lot-traceability.step3": "对于按重量出售个商品，记录到达个实际重量。应用程序据此计算每磅或者每公斤个真实成本，使食谱成本保持诚实。",
  "training.lessons.owner-lot-traceability.step4": "如果批次被召回，请将渠下架：批次被锁定以便无人能使用，下架本身成为记录，剩余部分连同原因流入废弃日志。",
